CREATE TABLE IF NOT EXISTS arcade_runs (id TEXT PRIMARY KEY, discord_id TEXT NOT NULL, version TEXT NOT NULL, team TEXT NOT NULL, state TEXT NOT NULL, seq INTEGER NOT NULL DEFAULT 0, ticks INTEGER NOT NULL DEFAULT 0, started_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, commit_token TEXT, finished INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS arcade_bests (discord_id TEXT NOT NULL, version TEXT NOT NULL, team TEXT NOT NULL, score INTEGER NOT NULL, level INTEGER NOT NULL, achieved_at INTEGER NOT NULL, PRIMARY KEY(discord_id,version));
